# -*- coding: utf-8 -*-
# BIRZHA_08_09_V1
"""
ЗАПИСЬ 08.09 В ГЛАВНЫЙ ДОКУМЕНТ БИРЖИ.

Дописывает строку в хронику `БИРЖА.md` и правит два места, которые
после сегодняшнего стали неверными.

ПОЧЕМУ ДВЕ ПРАВКИ, А НЕ ТОЛЬКО СТРОКА

1. В разделе про взгляд ОБОРВАН АБЗАЦ — текст начинается с середины
   фразы «успело произойти — импульс сформирован или только начался».
   Начала нет: потерялось правило о том, что излом в моменте не
   увидеть и воротами его ставить нельзя. Нашлось при сверке 08.09.
   Восстанавливаем.

2. Про приседающий бар в `БИРЖА.md` сказано «цена вниз, объём вверх».
   Это неточно и расходится со знаниями трейдера, где верно: МАЛО
   ХОДА при большом объёме. Приседающий не про то, куда пошла цена, а
   про то, что она почти не сдвинулась. Уточнено Шефом 08.09.

Запускать из корня репозитория:
    python dopisat_birzhu_08_09.py

Идемпотентен (маркер BIRZHA_08_09_V1). Рядом .bak.
"""
from __future__ import annotations
from pathlib import Path

MARKER = "BIRZHA_08_09_V1"
FAYL = "БИРЖА.md"


STROKA = """| 08.09 | **Найдена и починена настоящая причина, почему ВСЕ модели врали про график: растущая свеча была невидима** — фон кадра `#fdf6e3`, растущая свеча `#f2f2f2`, контраст 1.04:1 (неотличимо) при падающей 10.5:1; держал её только волосяной контур, а провайдеры уменьшают картинку перед показом модели. Модель видела тёмную массу на падениях и пустоту на росте — отсюда путаница направления у Haiku, Gemini и Sonnet сразу. Кадр переведён на тёмный фон (как в терминале Шефа): растущая 17.2:1, падающая 3.9:1, между собой 4.5:1. Полумеры проверены счётом и забракованы. **Зрение подтверждено контрольной меткой** — код из двух букв и двух цифр в углу кадра, нового при каждой отрисовке, нет ни на столе, ни в промпте; Илья назвал `MC93` верно, потом посчитал столбики AO по картинке. Приседающие выведены строчкой красных кружков на кадре (считает ядро, не рисовалка). Живой кадр трейдера теперь виден Шефу; «старший этаж узнаётся только рукой, „не смотрел“ — законный ответ». **Канон вечера, слово Шефа:** дивер не сигнал разворота, а показатель, что импульс выдохся — что дальше, покажет рынок; считать диверы не надо; диверы есть всегда, потому что это фрактальное устройство, а не находка; **дивергенция — это две линии: по краям цены и по краям горбов, разошлись — ход выдыхается** (работает в обе стороны, помнить нечего); блюдце — не вход, а свидетельство, что пятая волна на каком-то уровне была; четвёртая волна пересекает ноль «как правило», а не «обязана» — это свойство масштаба (100-150 баров), отсутствие пересечения читается как «смени этаж», а не «места нет»; **разворотный бар — это ВОПРОС, а не событие**: в молодом ходе передышка, в выдохшемся место, смысл даёт место, а не прибор — этим объясняется провал всех шести фильтров; правило трёх одно на всё: три раза ошибся подряд — остановись и подумай; разбор структуры — инструмент ВЕДЕНИЯ, а не входа. **Задача трейдера переписана**: не «реши, входить или нет», а «идти с ходом» (первый вопрос — иду я с чем-нибудь; номера волн до входа не спрашиваются; три места входа схлопнуты в одно — конец хода; счёт изломов убран). Полка знаний разделена по МОМЕНТУ РАБОТЫ: наверху «чтобы войти», в `знания/ведение/` — «чтобы вести», достаётся рукой `razbor_struktury`. Подача знаний исправлена: горб = мера силы/размаха на выбранном масштабе (НЕ «свежие деньги» — из AO это не следует, поправка Шефа), одна дивергенция вместо двух разных на полке. **Память: метка стала ключом-закладкой** — общая часть у всех одинакова (когда, откуда, от кого), личная своя (ярлыки его словами, важность его глазами; важность ставит только сам житель). Поиск по закладке весит как пять слов, можно спросить и по имени. **Найдена настоящая причина старого долга:** у меток и маяков нет поля «контекст» вовсе, и рабочий поиск отсеивал их ЦЕЛИКОМ — весь торговый опыт трейдера был невидим его же рабочему поиску; починено чтением, а не записью (голос «рынок» сохранён). Даны руки: `moi_yarlyki`, `zapomnit_s_yarlykom`, `vspomnit_po_yarlyku`. Картина трейдера запомнила ХОД: направление, этаж (там же и конец ищи) и счётчик попыток с предупреждением на третьей. В кабинете три иконки чата (сохранить/достать/очистить) и кнопка «Осмыслить» — житель сам пишет вывод по последним своим словам, и вывод ложится ему в память КАК РАБОЧИЙ. Живой случай Шефа: вошёл на минутках в разворот со стопом 10 пунктов, снял 25 — «торговля не попал/не попал, а просто ты в волне идёшь, где смог». Отложено: замер входа на младшем этаже (волна 1 на H4 — два бара, потому и не мерилось) — сперва пусть научится находить конец хода |
"""


OBORVANO_OLD = """успело произойти — импульс сформирован или только начался."""

OBORVANO_NEW = """**Излом в момент бара не увидеть никогда** — он опознаётся только
задним числом, когда движение уже пошло. Поэтому изломом нельзя
ставить ворота «если излом, то входи»: в нужный момент его ещё нет.
Порядок обратный: сперва увидел точку ноль, потом смотришь, что
успело произойти — импульс сформирован или только начался."""


SQUAT_OLD = """цена вниз, объём вверх"""

SQUAT_NEW = """мало хода при большом объёме (цена почти не сдвинулась) — BIRZHA_08_09_V1: было «цена вниз, объём вверх», неточно и расходилось со знаниями трейдера; приседающий не про то, куда пошла цена, а про то, что она почти не сдвинулась"""


def main() -> None:
    root = Path(__file__).resolve().parent
    p = root / FAYL
    if not p.exists():
        print(f"НЕ НАШЁЛ: {p}")
        print("Запускать из корня репозитория (там, где лежит main.py).")
        return

    t = p.read_text(encoding="utf-8")
    if MARKER in t:
        print("уже дописано — маркер на месте, ничего не трогаю")
        return

    sdelano = []

    # 1) строка в хронику — в самый конец
    t = t.rstrip("\n") + "\n" + STROKA
    sdelano.append("строка 08.09 дописана в хронику")

    # 2) восстановить оборванный абзац
    n = t.count(OBORVANO_OLD)
    if n == 1:
        t = t.replace(OBORVANO_OLD, OBORVANO_NEW, 1)
        sdelano.append("восстановлен оборванный абзац про излом")
    else:
        sdelano.append(f"⚠ оборванный абзац: совпадений {n} — не трогал")

    # 3) уточнить приседающий
    n = t.count(SQUAT_OLD)
    if n == 1:
        t = t.replace(SQUAT_OLD, SQUAT_NEW, 1)
        sdelano.append("уточнён приседающий бар")
    else:
        sdelano.append(f"⚠ приседающий: совпадений {n} — не трогал")

    t = t.rstrip("\n") + f"\n\n<!-- {MARKER} -->\n"

    bak = p.with_suffix(".md.bak_08_09")
    if not bak.exists():
        bak.write_text(p.read_text(encoding="utf-8"), encoding="utf-8")
    p.write_text(t, encoding="utf-8")

    for s in sdelano:
        print(("✔ " if not s.startswith("⚠") else "") + s)
    print("\nБэкап рядом:", bak.name)


if __name__ == "__main__":
    main()
